-- Taller mecánico: clientes y sus órdenes de servicio.
DROP TABLE IF EXISTS "Ordenes";
DROP TABLE IF EXISTS "Clientes";

CREATE TABLE "Clientes" (
    "Id"        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Documento" character varying(15)  NOT NULL,
    "Nombre"    character varying(100) NOT NULL,
    "Telefono"  character varying(20)  NOT NULL,
    "Correo"    character varying(120) NOT NULL,
    CONSTRAINT "UQ_Clientes_Documento" UNIQUE ("Documento")
);

CREATE TABLE "Ordenes" (
    "Id"            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Numero"        character varying(20)  NOT NULL,
    "Placa"         character varying(10)  NOT NULL,
    "Descripcion"   character varying(250) NOT NULL,
    "Estado"        character varying(20)  NOT NULL,
    "CostoEstimado" numeric(10,2)          NOT NULL,
    "FechaIngreso"  date                   NOT NULL,
    "ClienteId"     integer                NOT NULL,
    CONSTRAINT "UQ_Ordenes_Numero" UNIQUE ("Numero"),
    CONSTRAINT "FK_Ordenes_Clientes" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id")
);

